resources.preRequestScript:
const target = new URL(insomnia.environment.get('base_url'));
if (!['localhost', '127.0.0.1'].includes(target.hostname) || target.port !== '18080') throw new Error('Use the isolated local backend on port 18080; these requests write test fixtures.');
const run=Date.now().toString(); insomnia.environment.set('run_id',run); insomnia.environment.set('tool_name','INSO Drill '+run); const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota'}).format(new Date()); insomnia.environment.set('rental_date',today); const next=new Date(Date.now()+86400000); insomnia.environment.set('decline_date',new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota'}).format(next));

resources.afterResponseScript:
insomnia.test('01 Public features and initialize fixture identities: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("Fictional provider is enabled", () => { insomnia.expect(json.paymentProvider).to.eql('FICTIONAL_GATEWAY'); });

insomnia.test('02 Protected route without JWT: HTTP 401', () => insomnia.expect(insomnia.response.code).to.eql(401));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("Stable authentication problem", () => { insomnia.expect(json.code).to.eql('AUTHENTICATION_REQUIRED'); insomnia.expect(json.traceId).to.be.a('string'); });

insomnia.test('04 Public catalog and category reference: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("Catalog uses published server data", () => { insomnia.expect(json.length).to.be.above(0); });insomnia.environment.set('category_id', json[0].categoryId);

insomnia.test('05 Login supplier: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("supplier JWT and role", () => { insomnia.expect(json.accessToken).to.be.a('string'); insomnia.expect(json.roles).to.include('SUPPLIER'); });insomnia.environment.set('supplier_token', json.accessToken);const refreshCookie=insomnia.response.headers.find(h=>h.key.toLowerCase()==='set-cookie' && h.value.startsWith('trp_refresh=')); if(refreshCookie) insomnia.environment.set('supplier_refresh',refreshCookie.value.split(';')[0]);

insomnia.test('06 POST supplier tool: HTTP 201', () => insomnia.expect(insomnia.response.code).to.eql(201));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.environment.set('tool_id', json.id.value);insomnia.test("Tool has its persisted identity", () => { insomnia.expect(json.id.value).to.be.a("string"); });

insomnia.test('07 PUT supplier tool: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("PUT returns updated fields", () => { insomnia.expect(json.name).to.include('Updated'); });

insomnia.test('08 GET persisted supplier tool: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("Fresh read preserves PUT", () => { insomnia.expect(json.name).to.include('Updated'); insomnia.expect(json.dailyRate.amount).to.eql(25000); insomnia.expect(json.dailyRate.currency).to.eql('COP'); });

insomnia.test('11 Withdrawal preserves private tool history: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("DELETE is a logical withdrawal", () => { insomnia.expect(json.published).to.eql(false); });

insomnia.test('13 Register a physical equipment unit: HTTP 201', () => insomnia.expect(insomnia.response.code).to.eql(201));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.environment.set('unit_id', json.id.value);

insomnia.test('14 Login customer: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("customer JWT and role", () => { insomnia.expect(json.accessToken).to.be.a('string'); insomnia.expect(json.roles).to.include('CUSTOMER'); });insomnia.environment.set('customer_token', json.accessToken);const refreshCookie=insomnia.response.headers.find(h=>h.key.toLowerCase()==='set-cookie' && h.value.startsWith('trp_refresh=')); if(refreshCookie) insomnia.environment.set('customer_refresh',refreshCookie.value.split(';')[0]);

