insomnia.test("Checkout is idempotent", () => { insomnia.expect(json.paymentId).to.eql(insomnia.environment.get('payment_id')); });

insomnia.test('23 Payment confirms the reservation: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
insomnia.test("Reservation is confirmed", () => { insomnia.expect(json.status).to.eql('CONFIRMED'); });

insomnia.test('24 Exactly one academic receipt is issued: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
let json; try { json = insomnia.response.json(); } catch {}
const invoices=json.filter(row=>row.reservationId===insomnia.environment.get('reservation_id'));insomnia.test("One receipt despite duplicate approval", () => { insomnia.expect(invoices.length).to.eql(1); });insomnia.environment.set('invoice_id', invoices[0].invoiceId);

insomnia.test('25 Download academic receipt PDF: HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
